// Read what came back. In DISCOVERY mode, read it and write nothing.
//
// MEMORY. This node walks the payload ONCE and keeps only the small fields it
// needs. It never stringifies the response and never builds a second array of
// events - against the 26 MB discovery response that is the difference between
// a report and an out-of-memory.

const build = $('Build requests').all().map(i => i.json);
const mode  = (build[0] && build[0].mode) || 'targeted';
const cfg   = $('Config').first().json;
const cities = $('Load cities').all().map(i => i.json);

/** Walk every event in the response without concatenating them. */
function* eachEvent() {
  for (const it of $('Fetch markets').all()) {
    const j = it.json;
    if (!j) continue;
    const list = Array.isArray(j) ? j
               : (Array.isArray(j.data) ? j.data : (Array.isArray(j.events) ? j.events : null));
    if (list) { for (const ev of list) yield ev; } else { yield j; }
  }
}

// ---- DISCOVERY: report the real slug format, write nothing ---------------
if (mode === 'discovery') {
  const LOOKS_LIKE = /temperature|temp-in|highest-temp|weather|degrees/i;
  const samples = [];
  const cityWords = new Set();
  let nEvents = 0;

  for (const ev of eachEvent()) {
    if (!ev) continue;
    nEvents++;
    const slug = String(ev.slug || ev.event_slug || '');
    if (!slug || !LOOKS_LIKE.test(slug)) continue;
    if (samples.length < 25) {
      samples.push({
        slug,
        end_date: ev.endDate || ev.end_date || null,
        n_markets: Array.isArray(ev.markets) ? ev.markets.length : 0,
        first_bucket: (Array.isArray(ev.markets) && ev.markets[0])
          ? (ev.markets[0].groupItemTitle || ev.markets[0].question || null) : null,
      });
    }
    // Pull the word that sits where the city goes, so a city_key that does not
    // appear in the slug is visible as the mismatch it is.
    const m = slug.match(/(?:temperature|temp)-in-([a-z0-9-]+?)-on-/i);
    if (m) cityWords.add(m[1]);
  }

  return [{ json: {
    mode: 'discovery',
    n_events: nEvents,
    n_temperature_events: samples.length,
    samples,
    city_words: Array.from(cityWords).sort(),
    your_city_keys: cities.map(c => c.city_key).slice(0, 60),
    markets: [], bands: [], n_markets: 0, n_bands: 0,
    skipped_no_city: 0, band_parse_failed: 0, failed_labels: [], dates: [],
  }}];
}

// ---- TARGETED -------------------------------------------------------------
const MAX_EVENTS = Math.max(1, Number(cfg.max_events || 200));
const MAX_BANDS  = Math.max(1, Number(cfg.max_bands || 4000));

// markets.market_id and bands.band_id are uuid columns, and Polymarket's own
// ids are numeric strings and 0x hex - neither is a uuid. They must also be
// STABLE across runs or every run inserts duplicates instead of upserting.
function uuidFrom(str) {
  const s = String(str);
  let h = '';
  for (let salt = 0; salt < 4; salt++) {
    let v = 0x811c9dc5 ^ salt;
    for (let i = 0; i < s.length; i++) { v ^= s.charCodeAt(i); v = Math.imul(v, 0x01000193) >>> 0; }
    h += v.toString(16).padStart(8, '0');
  }
  return [h.slice(0,8), h.slice(8,12), '4'+h.slice(13,16),
          ((parseInt(h[16],16) & 0x3 | 0x8).toString(16))+h.slice(17,20), h.slice(20,32)].join('-');
}

// Polymarket states the bucket in TEXT, and band_lo/band_hi are what the
// probability lattice, every edge and band_contains() in ad4_34 all read. A
// band with null bounds cannot be priced. Half-open [lo, hi): "70-71F" settles
// on an integer high of 70 or 71, so it is [70, 72).
function parseBucket(text) {
  if (!text) return null;
  const t = String(text).replace(/[°℉℃]/g, ' ').replace(/[–—]/g, '-').toLowerCase()
                        .replace(/(\d)\s*[fc](?![a-z])/g, '$1')
                        .replace(/\s+/g, ' ').trim();
  const num = '(-?\\d+(?:\\.\\d+)?)';
  let m = t.match(new RegExp('^' + num + '\\s*(?:-|to)\\s*' + num));
  if (m) {
    const lo = parseFloat(m[1]), hi = parseFloat(m[2]);
    const step = Number.isInteger(lo) && Number.isInteger(hi) ? 1 : 0;
    return { lo, hi: hi + step, open_low: false, open_high: false };
  }
  m = t.match(new RegExp('^' + num + '\\s*(?:\\+|or (?:above|higher|more)|and (?:above|up|higher))'))
      || t.match(new RegExp('^(?:above|over|at least|greater than)\\s*' + num));
  if (m) return { lo: parseFloat(m[1]), hi: null, open_low: false, open_high: true };
  m = t.match(new RegExp('^' + num + '\\s*(?:-|or (?:below|less|lower|fewer))'))
      || t.match(new RegExp('^(?:below|under|less than|at most)\\s*' + num));
  if (m) {
    const v = parseFloat(m[1]);
    return { lo: null, hi: /or (below|less|lower|fewer)/.test(t) ? v + 1 : v,
             open_low: true, open_high: false };
  }
  m = t.match(new RegExp('^' + num + '\\s*$'));
  if (m) {
    const v = parseFloat(m[1]);
    return { lo: v, hi: Number.isInteger(v) ? v + 1 : v, open_low: false, open_high: false };
  }
  return null;
}

// Gamma gives endDate, and for a US market that is typically 04:00-05:00 UTC on
// the day AFTER the local trading day. Rolling an early-UTC end time back one
// day recovers the local day. Check the dates the Summary prints on the first
// run: getting this wrong shifts every market by a day and nothing downstream
// can tell.
function resolutionDate(ev, fallback) {
  const iso = ev.endDate || ev.end_date || null;
  if (!iso) return fallback || null;
  const d = new Date(iso);
  if (isNaN(d.getTime())) return fallback || null;
  if (d.getUTCHours() < 12) d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

function tokensOf(mk) {
  let raw = mk.clobTokenIds ?? mk.clob_token_ids ?? mk.tokens ?? null;   // a JSON STRING, not an array
  if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch { raw = null; } }
  if (!Array.isArray(raw)) return [null, null];
  const n = raw.map(t => (t && typeof t === 'object') ? (t.token_id ?? t.tokenId ?? null) : t);
  return [n[0] ?? null, n[1] ?? null];
}

// Each request was built for a known city and day, so the response is matched
// back to the request that asked for it rather than guessed at from the slug.
const asked = new Map();
for (const b of build) if (b && b.slug) asked.set(String(b.slug).toLowerCase(), b);
const byKey = new Map(cities.map(c => [c.city_key, c]));

const markets = [], bands = [];
let nEvents = 0, skippedNoCity = 0, bandParseFailed = 0, capped = false, notFound = 0;
const failedLabels = [], datesSeen = new Set(), missedSlugs = [];

for (const ev of eachEvent()) {
  if (!ev || typeof ev !== 'object') continue;
  nEvents++;
  if (markets.length >= MAX_EVENTS || bands.length >= MAX_BANDS) { capped = true; break; }

  const slug = String(ev.slug || ev.event_slug || '');
  const req  = asked.get(slug.toLowerCase());
  const city = req ? byKey.get(req.city_key) : null;
  if (!city) { skippedNoCity++; continue; }

  const inner = Array.isArray(ev.markets) ? ev.markets : [];
  if (inner.length === 0) continue;

  const forDate  = resolutionDate(ev, req.for_date);
  if (forDate) datesSeen.add(forDate);
  const marketId = uuidFrom('ad4:market:' + (slug || ev.id));
  const before   = bands.length;

  for (let idx = 0; idx < inner.length; idx++) {
    if (bands.length >= MAX_BANDS) { capped = true; break; }
    const mk = inner[idx];
    if (!mk) continue;
    const label = mk.groupItemTitle || mk.group_item_title || mk.outcome || mk.question || '';
    const b = parseBucket(label)
           || parseBucket(String(mk.question || '').replace(/^.*\bbe\b\s*/i, '').replace(/\?\s*$/, ''));
    if (!b) {
      bandParseFailed++;
      if (failedLabels.length < 5) failedLabels.push(String(label).slice(0, 60));
      continue;
    }
    const [yes, no] = tokensOf(mk);
    bands.push({
      band_id: uuidFrom('ad4:band:' + (mk.conditionId || mk.condition_id || (slug + ':' + idx))),
      market_id: marketId, band_index: idx,
      band_label: String(label).trim() || null,
      band_lo: b.lo, band_hi: b.hi, open_low: b.open_low, open_high: b.open_high,
      condition_id: mk.conditionId || mk.condition_id || null,
      token_yes: yes, token_no: no,
    });
  }

  if (bands.length === before) continue;
  markets.push({
    market_id: marketId, city_key: city.city_key, resolution_date: forDate,
    event_slug: slug || null, title: ev.title || ev.question || null,
    unit: city.unit || 'C', band_count: bands.length - before,
    closed: Boolean(ev.closed), condition_id: ev.conditionId || ev.condition_id || null,
    last_seen_at: new Date().toISOString(),
  });
}

// Which slugs we asked for and got nothing back for - the number that says
// whether the template is right.
const got = new Set(markets.map(m => String(m.event_slug || '').toLowerCase()));
for (const [slug] of asked) if (!got.has(slug)) { notFound++; if (missedSlugs.length < 5) missedSlugs.push(slug); }

// band_index is the ladder position, not the order Polymarket listed them.
const byMarket = {};
for (const b of bands) (byMarket[b.market_id] = byMarket[b.market_id] || []).push(b);
for (const list of Object.values(byMarket)) {
  list.sort((x, y) => (x.band_lo ?? -1e9) - (y.band_lo ?? -1e9));
  list.forEach((b, i) => { b.band_index = i; });
}
// band_count is what the desk can PRICE. The overround check sums a ladder and
// reads a short one as a cheap book.
for (const m of markets) m.band_count = (byMarket[m.market_id] || []).length;

return [{ json: {
  mode: 'targeted', markets, bands,
  n_markets: markets.length, n_bands: bands.length, n_events: nEvents,
  n_requested: asked.size, not_found: notFound, missed_slugs: missedSlugs,
  skipped_no_city: skippedNoCity, band_parse_failed: bandParseFailed,
  failed_labels: failedLabels, dates: Array.from(datesSeen).sort(),
  capped, n_raw: nEvents,
}}];

const p = $('Parse markets + bands').first().json;

// ---- DISCOVERY: report and stop. Nothing is written, on purpose. ---------
if (p.mode === 'discovery') {
  if (p.n_temperature_events === 0) {
    throw new Error(
      `DISCOVERY: looked at ${p.n_events} event(s) and none of their slugs mentioned ` +
      `temperature or weather. Either discovery_url in Config points somewhere that does not ` +
      `list them, or Polymarket names them differently. Open any weather market on ` +
      `polymarket.com and copy the slug out of the address bar - it is the part after ` +
      `/event/ - then set slug_template in Config with {city}, {month} and {day} in place ` +
      `of the city and the date. Nothing was written.`);
  }
  const lines = p.samples.slice(0, 8).map(s =>
    `  ${s.slug}   (${s.n_markets} buckets, first: ${s.first_bucket || '?'})`).join('\n');
  throw new Error(
    `DISCOVERY COMPLETE - nothing was written, which is what this mode is for.\n\n` +
    `Found ${p.n_temperature_events} temperature event(s) out of ${p.n_events}. Real slugs:\n\n` +
    `${lines}\n\n` +
    `The city appears in them as: ${p.city_words.join(', ') || '(could not tell)'}\n` +
    `Your cities table uses: ${p.your_city_keys.join(', ')}\n\n` +
    `NOW: copy one of those slugs into slug_template in Config and replace the city with ` +
    `{city}, the month with {month} and the day number with {day}. For example\n` +
    `  highest-temperature-in-nyc-on-september-6\n` +
    `becomes\n` +
    `  highest-temperature-in-{city}-on-{month}-{day}\n\n` +
    `If the city word above does not match your city_key, add a mapping to ` +
    `city_slug_overrides, e.g. {"new_york":"nyc"}. Then run again.`);
}

// ---- TARGETED -----------------------------------------------------------
if (p.n_markets === 0) {
  throw new Error(
    `Asked Polymarket for ${p.n_requested} event slug(s) and got no usable market back ` +
    `(${p.not_found} returned nothing). Nothing was written. The slug_template in Config is ` +
    `almost certainly wrong for at least the city part. Slugs that came back empty: ` +
    `${(p.missed_slugs || []).join(', ')}. ` +
    `Clear slug_template and run again - the workflow will then list the real ones and print them.`);
}

// A BAND WITH NO NUMERIC BOUNDS CANNOT BE PRICED. Not by the probability
// lattice, not by any edge, not by band_contains() in ad4_34. Writing a ladder
// with holes in it is worse than writing nothing: the overround check reads it
// as a cheap book and every coverage figure computed from it is wrong.
const attempted = (p.n_bands || 0) + (p.band_parse_failed || 0);
if (attempted > 0 && p.band_parse_failed > attempted / 2) {
  throw new Error(
    `${p.band_parse_failed} of ${attempted} buckets had a label this workflow could not read, ` +
    `so their bounds would be null and nothing downstream can price them. Nothing was written. ` +
    `Labels it choked on: ${(p.failed_labels || []).join(' | ')}. Fix parseBucket() in ` +
    `"Parse markets + bands" - the patterns are at the top of the node.`);
}

return [{ json: p }];

// DID THE DATABASE ACTUALLY TAKE IT?
//
// Every write node here carries onError=continueRegularOutput, so the workflow
// walks straight past a rejected write and reaches this node looking healthy.
// That is how a run reports success having written nothing - which is exactly
// what happened: reads worked, every write was refused, and the only visible
// error was on the LAST node in the chain.
//
// With neverError on, a refusal arrives as the PostgREST error body instead of
// an exception, so it can be read and named here.
function writeError(node) {
  let items;
  try { items = $(node).all(); } catch (e) { return null; }
  for (const it of items || []) {
    const b = it && it.json;
    if (!b || typeof b !== 'object') continue;
    if (b.error && !b.code) return { node, code: null, message: String(b.error).slice(0, 300) };
    if (b.code || b.message) {
      return { node, code: b.code ?? null,
               message: b.message ?? '', details: b.details ?? null, hint: b.hint ?? null };
    }
  }
  return null;
}

const WRITE_NODES = ["Upsert markets", "Upsert bands"];
for (const node of WRITE_NODES) {
  const e = writeError(node);
  if (!e) continue;
  // 42501 is the one worth naming, because the cause is never the code.
  if (String(e.code) === '42501' || /permission denied/i.test(e.message)) {
    throw new Error(
      `Supabase REFUSED the write: ${e.message} (${e.code}). This is the ANON key in the ` +
      `Config node, not the service key - anon is granted SELECT and nothing else, which is ` +
      `why reads worked and every write was silently dropped. Open Config -> service_key and ` +
      `paste the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or a ` +
      `key beginning sb_secret_). NEVER put that key anywhere starting NEXT_PUBLIC_. ` +
      `Failing node: ${e.node}. Nothing was written.`);
  }
  throw new Error(
    `Supabase refused the write at "${e.node}": ${e.message}` +
    (e.code ? ` (${e.code})` : '') + (e.details ? ` - ${e.details}` : '') +
    (e.hint ? ` Hint: ${e.hint}` : '') + ' Nothing was written.');
}

const p = $('Parse markets + bands').first().json;
const rows = (p.n_markets || 0) + (p.n_bands || 0);
const failed = p.band_parse_failed || 0;

// CHECK THE DATES ON THE FIRST RUN. They come from endDate rolled back a day
// when it lands before noon UTC; if they are all one day out, that rule is a
// single function at the top of the parse node.
const summary =
  `AD4 P0.2: ${p.n_markets} market(s), ${p.n_bands} band(s) from ${p.n_requested} slug(s) asked for` +
  (p.not_found ? `, ${p.not_found} of which returned nothing` : '') + '. ' +
  `Settlement dates: ${(p.dates || []).join(', ') || 'none'}.` +
  (failed ? ` ${failed} bucket label(s) unreadable: ${(p.failed_labels || []).join(' | ')}.` : '');

const status = rows > 0 ? ((failed || p.not_found) ? 'attention' : 'ok') : 'attention';
const detail = { n_markets: p.n_markets, n_bands: p.n_bands, n_requested: p.n_requested,
                 not_found: p.not_found, missed_slugs: p.missed_slugs || [],
                 band_parse_failed: failed, failed_labels: p.failed_labels || [],
                 dates: p.dates || [], capped: p.capped };
return [{ json: {
  summary, status, rows,
  log: { p_job: 'P0.2_market_discovery', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
}}];

// AN ENDPOINT THIS FILE CANNOT KNOW.
//
// P0.2-P0.5 are RECONSTRUCTIONS. The Supabase half is grounded in the real
// schema and is safe; the Polymarket half never was. These files used to ship
// with a plausible-looking URL already filled in, which is worse than shipping
// none: it reads as authoritative, so nobody changes it, and the run dies four
// nodes later with a message about response shapes. That is exactly how this
// wasted an afternoon.
//
// So the field ships EMPTY and the run stops here - before any HTTP call,
// before any database read - saying where the real value is.
{
  const cfg = $('Config').first().json ?? {};
  const missing = Object.keys(cfg)
    .filter((k) => k.endsWith('_url') && k !== 'supabase_url')
    .filter((k) => !String(cfg[k] ?? '').trim());
  if (missing.length) {
    throw new Error(
      `Config.${missing.join(' and Config.')} is empty, and this file cannot fill it in. ` +
      `Open your OWN working P0.2-P0.5 in n8n, click its Polymarket HTTP node, copy the URL ` +
      `from it, and paste it here. Those workflows are what put 841 markets and 122,000 trades ` +
      `in this database - they are the authority on the endpoint, not this reconstruction. ` +
      `Nothing was fetched and nothing was written.`);
  }
}

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE. 42501 here means the key
// cannot call should_run, and a key that cannot do that cannot write either -
// so stop, rather than failing open into a run that writes nothing.
//
// THIS IS NOT THE MAIN DEFENCE AND MUST NOT BE MISTAKEN FOR IT. sql/ad4_20
// grants should_run to anon ON PURPOSE, so the Workflows page can preview a
// schedule change before saving it. On a database with that grant - which is
// every database that ran ad4_20 - an anon key sails straight through this
// check and only fails at the first WRITE. The write guard in the Summary
// node is what actually catches it; run section 6 of sql/ad4_diagnose.sql to
// see which key can write what before spending a run finding out.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). This is the ANON ` +
    `key in the Config node, not the service key - anon is granted SELECT and nothing else. ` +
    `Every write in this workflow would be refused the same way. Open Config -> service_key ` +
    `and paste the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or ` +
    `a key beginning sb_secret_). NEVER put that key anywhere starting NEXT_PUBLIC_.`);
}

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;

// Decide what to ask Polymarket for - and ask for exactly that.
//
// WHY THIS NODE EXISTS. The first three versions of this workflow listed
// events and filtered client-side:
//
//     /events?closed=false&limit=200&tag_slug=weather   -> 200 events, assumed
//     /events?closed=false&limit=40                     -> 2160 events, actual
//
// Gamma ignored BOTH the tag filter and the limit. Twenty-six megabytes came
// back, none of it weather, and n8n fell over holding it. Every attempt to fix
// that was another guess at a parameter this repo cannot test - the machine
// that builds these files is blocked from polymarket.com.
//
// So the dependency is removed rather than guessed at again. A temperature
// market has a KNOWN SLUG: one per city per day. We know the cities and we
// know the days, so we can ask for each event by name. Each response is one
// event. Nothing depends on limit, on pagination, or on a tag taxonomy.
//
// TWO MODES, and the first run uses the second.
//
//   TARGETED   slug_template is set. Builds one URL per city per day and
//              fetches them. Bounded by construction.
//
//   DISCOVERY  slug_template is EMPTY, which is how this ships. One list call,
//              WRITES NOTHING, and reports the real slugs it can see so you can
//              read the actual format off your own account instead of taking
//              mine. Set slug_template from what it prints and run again.

const cfg    = $('Config').first().json;
const cities = $('Load cities').all().map(i => i.json);

const template = String(cfg.slug_template || '').trim();
const urlTmpl  = String(cfg.event_url_template || 'https://gamma-api.polymarket.com/events?slug={slug}').trim();

// ---- DISCOVERY ------------------------------------------------------------
if (!template) {
  const url = String(cfg.discovery_url || 'https://gamma-api.polymarket.com/events?closed=false').trim();
  if (!url) {
    throw new Error(
      'Both slug_template and discovery_url are empty in Config, so there is nothing to ask for. ' +
      'Leave slug_template empty and run once to discover the slug format.');
  }
  return [{ json: { mode: 'discovery', url } }];
}

// ---- TARGETED -------------------------------------------------------------
const MONTHS = ['january','february','march','april','may','june',
                'july','august','september','october','november','december'];

// Polymarket names a city the way a person would, which is not always the key
// this desk uses. display_name is the better guess; the override map is the
// answer when neither is right.
let overrides = {};
try { overrides = JSON.parse(String(cfg.city_slug_overrides || '{}')); } catch { overrides = {}; }

function citySlug(c) {
  if (overrides[c.city_key]) return String(overrides[c.city_key]);
  const name = c.display_name || c.city_key;
  return String(name).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

const days = Math.max(1, Math.min(14, Number(cfg.days_ahead || 2)));
const maxReq = Math.max(1, Number(cfg.max_requests || 120));

const out = [];
const today = new Date();
for (let d = 0; d < days && out.length < maxReq; d++) {
  const dt = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate() + d));
  const month = MONTHS[dt.getUTCMonth()];
  const day   = String(dt.getUTCDate());
  const iso   = dt.toISOString().slice(0, 10);
  for (const c of cities) {
    if (out.length >= maxReq) break;
    if (!c || !c.city_key) continue;
    const slug = template
      .replace(/\{city\}/g, citySlug(c))
      .replace(/\{month\}/g, month)
      .replace(/\{month_num\}/g, String(dt.getUTCMonth() + 1).padStart(2, '0'))
      .replace(/\{day\}/g, day)
      .replace(/\{day_pad\}/g, day.padStart(2, '0'))
      .replace(/\{date\}/g, iso)
      .replace(/\{year\}/g, String(dt.getUTCFullYear()));
    out.push({ json: {
      mode: 'targeted',
      city_key: c.city_key,
      for_date: iso,
      slug,
      url: urlTmpl.replace(/\{slug\}/g, encodeURIComponent(slug)),
    }});
  }
}

if (out.length === 0) {
  throw new Error(
    'No requests to make. Either the cities table is empty, or days_ahead is 0. ' +
    'Nothing was fetched and nothing was written.');
}
return out;
